/* Provider-bound automatic off-device backup.
 *
 * The portable data key is generated by SaagarPortableBackup, wrapped by the
 * Android Keystore and never persisted in clear text. The native
 * SaagarOffDevice plugin owns the persisted Storage Access Framework grant,
 * rejects on-device providers, verifies the copied bytes and applies GFS
 * retention. JavaScript authorizes every scheduled delivery against the exact
 * native destination id before placing an encrypted .sccbak in app cache.
 */
(function (root) {
  'use strict';

  var CONFIG_KEY = 'st_v2_offdevice_backup_config_v1';
  var CONFIG_VERSION = 1;
  var FAILURE_THRESHOLD_HOURS = 36;
  var AUTO_START_DELAY_MS = 10000;
  var AUTO_INTERVAL_MS = 6 * 60 * 60 * 1000;
  var SCOPE_ID = 'full-whitelisted-backup';
  var running = null;
  var nativeState = null;

  function fail(code, message) {
    var error = new Error(message || code);
    error.code = code;
    throw error;
  }

  function safeMessage(error) {
    return String(error && (error.code || error.message) || error || 'Unknown off-device backup failure')
      .replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, 160);
  }

  function readRaw() {
    try {
      if (typeof root.safeGet === 'function') return root.safeGet(CONFIG_KEY);
      return root.localStorage ? root.localStorage.getItem(CONFIG_KEY) : null;
    } catch (_) { return null; }
  }

  function writeRaw(value) {
    var text = JSON.stringify(value);
    try {
      var ok;
      if (typeof root.safeSet === 'function') ok = root.safeSet(CONFIG_KEY, text) !== false;
      else if (root.localStorage) { root.localStorage.setItem(CONFIG_KEY, text); ok = true; }
      else ok = false;
      if (!ok || readRaw() !== text) fail('CONFIG_WRITE_FAILED', 'Automatic-backup configuration could not be saved.');
    } catch (error) {
      if (error && error.code) throw error;
      fail('CONFIG_WRITE_FAILED', 'Automatic-backup configuration could not be saved.');
    }
  }

  function removeRaw() {
    try {
      var ok;
      if (typeof root.safeRemove === 'function') ok = root.safeRemove(CONFIG_KEY) !== false;
      else if (root.localStorage) { root.localStorage.removeItem(CONFIG_KEY); ok = true; }
      else ok = false;
      if (!ok || readRaw() !== null) fail('CONFIG_CLEAR_FAILED', 'Automatic-backup configuration could not be removed.');
    } catch (error) {
      if (error && error.code) throw error;
      fail('CONFIG_CLEAR_FAILED', 'Automatic-backup configuration could not be removed.');
    }
  }

  function cleanLabel(value) {
    return String(value || '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 100);
  }

  function validRecovery(value) {
    var kdf = value && value.kdf, cipher = value && value.cipher;
    return !!(value && typeof value === 'object' && !Array.isArray(value) &&
      kdf && kdf.name === 'PBKDF2' && kdf.hash === 'SHA-256' && Number.isInteger(kdf.iterations) &&
      kdf.iterations >= 100000 && kdf.iterations <= 1000000 && typeof kdf.salt === 'string' &&
      cipher && cipher.name === 'AES-GCM' && cipher.keyBits === 256 && cipher.tagBits === 128 &&
      typeof cipher.iv === 'string' && typeof value.wrappedKey === 'string');
  }

  function parseConfig() {
    var raw = readRaw();
    if (!raw) return { value: null, damaged: false };
    try {
      var value = JSON.parse(raw);
      if (!value || typeof value !== 'object' || Array.isArray(value) || value.version !== CONFIG_VERSION ||
          !/^[a-f0-9]{64}$/.test(String(value.destinationId || '')) ||
          typeof value.wrappedKey !== 'string' || !/^[A-Za-z0-9+/]+={0,2}$/.test(value.wrappedKey) ||
          !validRecovery(value.recovery)) return { value: null, damaged: true };
      return { value: value, damaged: false };
    } catch (_) { return { value: null, damaged: true }; }
  }

  function context() {
    var capacitor = root.Capacitor;
    var native = !!(capacitor && typeof capacitor.isNativePlatform === 'function' && capacitor.isNativePlatform());
    var plugins = capacitor && capacitor.Plugins || {};
    return {
      native: native,
      offDevice: plugins.SaagarOffDevice || null,
      keystore: plugins.SaagarKeystore || null,
      fs: plugins.Filesystem || null
    };
  }

  function requireContext() {
    var c = context();
    if (!c.native || !c.offDevice || !c.keystore || !c.fs) {
      fail('OFFDEVICE_UNAVAILABLE', 'Automatic off-device backup is unavailable in this build.');
    }
    if (!root.SaagarPortableBackup || typeof root.SaagarPortableBackup.createRecoveryProfile !== 'function' ||
        typeof root.SaagarPortableBackup.sealWithKey !== 'function') {
      fail('ENCRYPTION_UNAVAILABLE', 'Portable backup encryption is unavailable.');
    }
    if (!root.SaagarExportControl || typeof root.SaagarExportControl.authorizeScheduled !== 'function') {
      fail('EXPORT_CONTROL_UNAVAILABLE', 'Scheduled export control is unavailable.');
    }
    return c;
  }

  function dateKey(date) {
    function pad(value) { return value < 10 ? '0' + value : String(value); }
    return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate());
  }

  function failureEscalated(config) {
    if (!config || !config.consecutiveFailures) return false;
    var since = Date.parse(config.lastSuccessAt || config.firstFailureAt || '');
    return isFinite(since) && Date.now() - since >= FAILURE_THRESHOLD_HOURS * 60 * 60 * 1000;
  }

  function status() {
    var parsed = parseConfig(), config = parsed.value;
    var permissionKnownBad = nativeState && nativeState.configured === false;
    return {
      configured: !!config && !permissionKnownBad,
      damaged: parsed.damaged,
      destinationId: config ? config.destinationId : '',
      destinationLabel: config ? cleanLabel(config.destinationLabel) || 'Off-device folder' : '',
      provider: config ? cleanLabel(config.provider) : '',
      lastAttemptAt: config && config.lastAttemptAt || null,
      lastSuccessAt: config && config.lastSuccessAt || null,
      lastFailureAt: config && config.lastFailureAt || null,
      lastError: config && config.lastError || (permissionKnownBad ? cleanLabel(nativeState.reason || 'permission-missing') : null),
      consecutiveFailures: config && Number(config.consecutiveFailures || 0) || 0,
      failureEscalated: failureEscalated(config),
      failureThresholdHours: FAILURE_THRESHOLD_HOURS,
      running: !!running
    };
  }

  function exportMeta(destinationId) {
    return {
      exportId: 'automatic-offdevice-backup',
      kind: 'encrypted-backup',
      scopeId: SCOPE_ID,
      scopeLabel: 'full whitelisted application backup',
      module: 'settings',
      rowCount: 0,
      fileName: 'automatic.sccbak',
      purposeId: 'automatic-offdevice-recovery',
      destinationId: destinationId
    };
  }

  function toBase64(text) {
    if (typeof root.TextEncoder !== 'function') fail('ENCODING_UNAVAILABLE', 'Backup encoding is unavailable.');
    var bytes = new root.TextEncoder().encode(text), binary = '', step = 0x8000;
    for (var i = 0; i < bytes.length; i += step) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(i + step, bytes.length)));
    }
    return root.btoa(binary);
  }

  function markFailure(config, error) {
    if (!config) return;
    var when = new Date().toISOString();
    config.lastFailureAt = when;
    if (!Number(config.consecutiveFailures || 0)) config.firstFailureAt = when;
    config.consecutiveFailures = Number(config.consecutiveFailures || 0) + 1;
    config.lastError = safeMessage(error);
    try { writeRaw(config); } catch (_) {}
  }

  async function refreshNativeStatus() {
    var c = context();
    if (!c.native || !c.offDevice || typeof c.offDevice.status !== 'function') {
      nativeState = { configured: false, reason: 'native-provider-unavailable' };
      return nativeState;
    }
    try { nativeState = await c.offDevice.status(); }
    catch (error) { nativeState = { configured: false, reason: safeMessage(error) }; }
    return nativeState;
  }

  async function configure(passphrase) {
    var c = requireContext();
    if (typeof passphrase !== 'string' || passphrase.length < 12) fail('WEAK_PASSPHRASE', 'Use a recovery passphrase with at least 12 characters.');
    if (typeof c.offDevice.chooseFolder !== 'function' || typeof c.keystore.wrapKey !== 'function') {
      fail('OFFDEVICE_UNAVAILABLE', 'Automatic off-device backup setup is unavailable.');
    }
    if (typeof c.keystore.available === 'function') {
      var available = await c.keystore.available();
      if (!available || available.available !== true) fail('KEYSTORE_UNAVAILABLE', 'Android Keystore protection is unavailable.');
    }
    var chosen = await c.offDevice.chooseFolder();
    if (!chosen || chosen.configured !== true || !/^[a-f0-9]{64}$/.test(String(chosen.destinationId || ''))) {
      fail('DESTINATION_UNVERIFIED', 'The selected off-device provider could not be verified.');
    }
    var created, wrapped;
    try {
      created = await root.SaagarPortableBackup.createRecoveryProfile(passphrase);
      wrapped = await c.keystore.wrapKey({ data: created.keyBase64 });
      if (!wrapped || typeof wrapped.wrapped !== 'string' || !wrapped.wrapped) fail('KEY_WRAP_FAILED', 'The portable backup key could not be protected.');
      created.keyBase64 = '';
      var config = {
        version: CONFIG_VERSION,
        destinationId: String(chosen.destinationId),
        destinationLabel: cleanLabel(chosen.label) || 'Off-device folder',
        provider: cleanLabel(chosen.provider),
        wrappedKey: wrapped.wrapped,
        recovery: created.profile,
        createdAt: new Date().toISOString(),
        lastAttemptAt: null,
        lastSuccessAt: null,
        lastFailureAt: null,
        firstFailureAt: null,
        lastError: null,
        consecutiveFailures: 0
      };
      writeRaw(config);
      var grant = await root.SaagarExportControl.approveScheduled(exportMeta(config.destinationId));
      if (!grant) {
        removeRaw();
        try { await c.offDevice.clearFolder(); } catch (_) {}
        fail('SCHEDULE_APPROVAL_REQUIRED', 'Standing owner approval was not granted.');
      }
      nativeState = chosen;
      return await run(true);
    } catch (error) {
      throw error;
    } finally {
      if (created) created.keyBase64 = '';
    }
  }

  async function performRun(force) {
    var parsed = parseConfig(), config = parsed.value;
    if (parsed.damaged) fail('CONFIG_DAMAGED', 'Automatic-backup configuration is damaged; set it up again.');
    if (!config) return { configured: false, verified: false };
    var c = requireContext(), token = null, cacheName = '';
    var today = dateKey(new Date());
    if (!force && config.lastSuccessAt) {
      var previous = new Date(config.lastSuccessAt);
      if (!isNaN(previous.getTime()) && dateKey(previous) === today) return { configured: true, verified: true, skipped: 'already-backed-up-today' };
    }
    config.lastAttemptAt = new Date().toISOString();
    writeRaw(config);
    try {
      var provider = await c.offDevice.status();
      nativeState = provider;
      if (!provider || provider.configured !== true || provider.destinationId !== config.destinationId) {
        fail('DESTINATION_MISMATCH', 'The approved off-device destination is unavailable or changed.');
      }
      token = root.SaagarExportControl.authorizeScheduled(exportMeta(config.destinationId));
      if (!token) fail('SCHEDULE_NOT_AUTHORIZED', 'The scheduled backup is not authorized for this destination.');
      if (typeof root.SaagarExportControl.beginDelivery !== 'function' || root.SaagarExportControl.beginDelivery(token) !== true) {
        fail('DELIVERY_REGISTER_FAILED', 'The scheduled backup delivery could not be registered.');
      }
      if (typeof c.keystore.unwrapKey !== 'function') fail('KEYSTORE_UNAVAILABLE', 'Android Keystore recovery is unavailable.');
      var unwrapped = await c.keystore.unwrapKey({ wrapped: config.wrappedKey });
      if (!unwrapped || typeof unwrapped.data !== 'string' || !unwrapped.data) fail('KEY_UNWRAP_FAILED', 'The portable backup key could not be recovered.');
      if (typeof root.backupPayload !== 'function') fail('BACKUP_PAYLOAD_INVALID', 'The whitelisted backup provider is unavailable.');
      var payload = root.backupPayload();
      var keyBase64 = unwrapped.data;
      unwrapped.data = '';
      var container;
      try { container = await root.SaagarPortableBackup.sealWithKey(payload, keyBase64, config.recovery); }
      finally { keyBase64 = ''; }
      var serialized = JSON.stringify(container);
      if (!root.SaagarPortableBackup.isContainer || root.SaagarPortableBackup.isContainer(container) !== true) {
        fail('ENCRYPTION_FAILED', 'The encrypted portable-backup container is invalid.');
      }
      cacheName = 'offdevice-' + today + '-' + Date.now().toString(36) + '.sccbak';
      await c.fs.writeFile({ path: cacheName, data: toBase64(serialized), directory: 'CACHE' });
      var copied = await c.offDevice.copyFromCache({ path: cacheName, date: today });
      if (!copied || copied.verified !== true) fail('COPY_NOT_VERIFIED', 'The off-device provider copy failed read-back verification.');
      if (copied.destinationId !== config.destinationId) fail('DESTINATION_MISMATCH', 'The verified copy was delivered to an unexpected destination.');
      var successAt = new Date().toISOString();
      config.lastSuccessAt = successAt;
      config.lastFailureAt = null;
      config.firstFailureAt = null;
      config.lastError = null;
      config.consecutiveFailures = 0;
      writeRaw(config);
      if (typeof root.setOffDeviceBackup !== 'function' || root.setOffDeviceBackup() === false) {
        fail('BACKUP_EVIDENCE_FAILED', 'The verified off-device backup marker could not be saved.');
      }
      if (typeof root.SaagarExportControl.recordOutcome !== 'function' || root.SaagarExportControl.recordOutcome(token, 'completed') !== true) {
        fail('DELIVERY_REGISTER_FAILED', 'The verified delivery outcome could not be registered.');
      }
      token = null;
      return {
        configured: true,
        verified: true,
        destinationId: config.destinationId,
        destinationLabel: config.destinationLabel,
        sha256: String(copied.sha256 || ''),
        size: Number(copied.size || 0),
        dailyFile: cleanLabel(copied.dailyFile)
      };
    } catch (error) {
      if (token && root.SaagarExportControl && typeof root.SaagarExportControl.recordOutcome === 'function') {
        try { root.SaagarExportControl.recordOutcome(token, 'failed'); } catch (_) {}
      }
      markFailure(config, error);
      throw error;
    } finally {
      if (cacheName) {
        try { await c.fs.deleteFile({ path: cacheName, directory: 'CACHE' }); } catch (_) {}
      }
    }
  }

  function run(force) {
    if (!running) running = Promise.resolve().then(function () { return performRun(force === true); }).finally(function () { running = null; });
    return running;
  }

  async function disable() {
    var c = requireContext();
    if (typeof root.SaagarExportControl.revokeScheduled !== 'function' || await root.SaagarExportControl.revokeScheduled() !== true) {
      fail('SCHEDULE_REVOKE_FAILED', 'Standing backup approval was not revoked.');
    }
    if (typeof c.offDevice.clearFolder !== 'function') fail('OFFDEVICE_UNAVAILABLE', 'The provider permission cannot be cleared.');
    await c.offDevice.clearFolder();
    removeRaw();
    nativeState = { configured: false };
    return { disabled: true };
  }

  root.SaagarOffDeviceBackup = Object.freeze({
    configure: configure,
    run: run,
    disable: disable,
    status: status
  });

  function schedule() {
    function automatic() {
      var parsed = parseConfig();
      if (!parsed.value || parsed.damaged) return;
      run(false).catch(function (error) { try { root.console.warn('[SaagarOffDeviceBackup]', safeMessage(error)); } catch (_) {} });
    }
    function ready() {
      if (root.SaagarStore && typeof root.SaagarStore.whenReady === 'function') root.SaagarStore.whenReady(automatic);
      else automatic();
    }
    if (typeof root.setTimeout === 'function') root.setTimeout(function () { refreshNativeStatus().then(ready); }, AUTO_START_DELAY_MS);
    if (typeof root.setInterval === 'function') root.setInterval(ready, AUTO_INTERVAL_MS);
  }

  schedule();
})(typeof window !== 'undefined' ? window : globalThis);
